import{_ as o,B as l,o as r,c as s,a8 as c,a as t,E as n,f as i}from"./chunks/framework.CNIpabDg.js";const x=JSON.parse('{"title":"Terminal (executable)","description":"The terminal executable provides a graphical terminal window exposed as a character device and uses it to host the command-line shell.","frontmatter":{"layout":"doc","docType":"explanation","description":"The terminal executable provides a graphical terminal window exposed as a character device and uses it to host the command-line shell."},"headers":[],"relativePath":"explanation/architecture/executables/terminal.md","filePath":"explanation/architecture/executables/terminal.md","lastUpdated":1793145952000}'),d={name:"explanation/architecture/executables/terminal.md"};function u(p,e,h,m,f,b){const a=l("CodeReference");return r(),s("div",{"data-pagefind-body":!0,"data-pagefind-meta":"date:1793145952000"},[e[5]||(e[5]=c('<h1 id="terminal-executable" tabindex="-1">Terminal (executable) <a class="header-anchor" href="#terminal-executable" aria-label="Permalink to &quot;Terminal (executable)&quot;">​</a></h1><p>The terminal executable provides a graphical terminal window exposed as a character device and uses it to host the command-line shell.</p><h2 id="role" tabindex="-1">Role <a class="header-anchor" href="#role" aria-label="Permalink to &quot;Role&quot;">​</a></h2><ul><li>Bridges GUI events and text I/O semantics through a mounted <code>/devices/terminal</code> device.</li><li>Launches <code>/binaries/command_line_shell</code> with terminal-backed stdin/stdout/stderr.</li></ul><h2 id="startup-and-lifecycle" tabindex="-1">Startup and lifecycle <a class="header-anchor" href="#startup-and-lifecycle" aria-label="Permalink to &quot;Startup and lifecycle&quot;">​</a></h2><ol><li>Creates <code>Terminal</code> UI object (window, label display, text input).</li><li>Mounts terminal object as <code>/devices/terminal</code> character device.</li><li>Opens <code>Standard</code> streams on that path.</li><li>Executes command-line shell executable.</li><li>Runs event loop until terminal window close/delete event.</li></ol><h2 id="runtime-integration-points" tabindex="-1">Runtime integration points <a class="header-anchor" href="#runtime-integration-points" aria-label="Permalink to &quot;Runtime integration points&quot;">​</a></h2><ul><li><code>virtual_file_system::mount_static</code> for runtime device registration.</li><li><code>xila::executable::execute</code> to start command-line shell child process.</li><li><code>graphics</code> and LVGL for window/input rendering.</li><li><code>shared::utf8_chunks</code> for buffered output write handling.</li></ul><h2 id="data-and-control-flow-vfs-touchpoints" tabindex="-1">Data and control flow / VFS touchpoints <a class="header-anchor" href="#data-and-control-flow-vfs-touchpoints" aria-label="Permalink to &quot;Data and control flow / VFS touchpoints&quot;">​</a></h2><ul><li>Write path: shell output -&gt; <code>/devices/terminal</code> -&gt; <code>DirectBaseOperations::write</code> -&gt; UI display append.</li><li>Read path: UI enter key -&gt; validated input queue -&gt; <code>/devices/terminal</code> read by shell.</li><li>Control flow: parent terminal loop keeps processing events while child shell uses same device streams.</li></ul><h2 id="concurrency-and-event-loop-model" tabindex="-1">Concurrency and event-loop model <a class="header-anchor" href="#concurrency-and-event-loop-model" aria-label="Permalink to &quot;Concurrency and event-loop model&quot;">​</a></h2><ul><li>Terminal executable runs a periodic loop with <code>sleep(20 ms)</code> while polling <code>handle_events</code>.</li><li>The GUI owns <code>RwLock&lt;CriticalSectionRawMutex, Inner&gt;</code> state. Reads also use a per-open <code>Waiter</code> and a bounded <code>WaitQueue&lt;16&gt;</code> to register wakers instead of repeatedly polling when input is empty.</li></ul><h2 id="failure-semantics" tabindex="-1">Failure semantics <a class="header-anchor" href="#failure-semantics" aria-label="Permalink to &quot;Failure semantics&quot;">​</a></h2><ul><li>Device mount/open/execute failures return executable error and are logged + printed.</li><li>Resource contention on terminal locks maps to <code>RessourceBusy</code> / <code>file_system::Error::RessourceBusy</code>.</li></ul><h2 id="contract-vs-implementation" tabindex="-1">Contract vs implementation <a class="header-anchor" href="#contract-vs-implementation" aria-label="Permalink to &quot;Contract vs implementation&quot;">​</a></h2><ul><li><strong>Contract</strong>: terminal executable exposes a character-device-backed text console and runs shell inside it.</li><li><strong>Current implementation</strong>: LVGL window + textarea, mounted static device node <code>/devices/terminal</code>, and shell child execution via executable runtime.</li></ul><h2 id="operational-limitations" tabindex="-1">Operational limitations <a class="header-anchor" href="#operational-limitations" aria-label="Permalink to &quot;Operational limitations&quot;">​</a></h2><ul><li>The input queue receives a line when Enter is pressed; no PTY or full ANSI terminal emulator is implemented. Output recognizes <strong>a small subset</strong> of ANSI-like clear/home sequences (<code>ESC[2J</code> and <code>ESC[H</code>) but not a general cursor/style parser.</li><li>UI/event loop cadence is fixed and may affect responsiveness under heavy output.</li></ul><h2 id="device-polling-input-ownership-and-cleanup" tabindex="-1">Device polling, input ownership and cleanup <a class="header-anchor" href="#device-polling-input-ownership-and-cleanup" aria-label="Permalink to &quot;Device polling, input ownership and cleanup&quot;">​</a></h2><p><code>TerminalExecutable::new(vfs, task)</code> installs the desktop shortcut. At runtime, <code>Terminal::new(graphics::ffi_manager())</code> creates the window and text widgets, and the launcher leaks the resulting <code>Terminal</code> into <code>&#39;static</code> storage before mounting it as a character device at <code>/devices/terminal</code>. The launcher opens the same device three times through <code>Standard::open</code> for stdin, stdout and stderr, then calls <code>executable::execute(..., &quot;/binaries/command_line_shell&quot;, ...)</code>.</p><p><strong>I/O contract:</strong> the device is a <strong>contextual</strong> <code>BaseOperations</code> + <code>CharacterDevice</code>, not a direct character device. Each open context gets its own <code>Waiter</code>. An empty blocking read registers a waker in <code>WaitQueue&lt;16&gt;</code> and returns <code>Poll::Pending</code>; cancellation and close unregister pending reads. When Enter is pressed, input bytes plus <code>\\n</code> enter the queue and registered readers are notified. Output runs through <code>shared::utf8_chunks</code>; invalid UTF-8 bytes are skipped rather than preserved byte for byte.</p><p>The terminal UI sleeps <strong>20 ms</strong> between event-processing calls while the command-line shell is scheduled independently. <code>print</code> uses try-locks and returns <code>RessourceBusy</code> under contention; the device maps this to <code>file_system::Error::RessourceBusy</code>.</p><p><strong>Current lifecycle limitation:</strong> the main executable ignores the returned shell <code>JoinHandle</code>; closing the window ends the terminal&#39;s outer event loop, but this code does not explicitly unmount <code>/devices/terminal</code>, free the leaked <code>Terminal</code> allocation, or join/terminate the shell child. Treat repeated mounts and window teardown as areas requiring dedicated lifecycle tests.</p><h3 id="source-and-api-references" tabindex="-1">Source and API references <a class="header-anchor" href="#source-and-api-references" aria-label="Permalink to &quot;Source and API references&quot;">​</a></h3>',24)),t("ul",null,[t("li",null,[n(a,{repo:"applications",path:"executables/terminal/src/lib.rs"}),e[0]||(e[0]=i(" — mount/open/launch sequence.",-1))]),t("li",null,[n(a,{repo:"applications",path:"executables/terminal/src/device.rs"}),e[1]||(e[1]=i(" — polling, cancellation and stream operations.",-1))]),t("li",null,[n(a,{repo:"applications",path:"executables/terminal/src/terminal.rs"}),e[2]||(e[2]=i(" — UI, input validation and output handling.",-1))]),t("li",null,[n(a,{repo:"applications",path:"executables/terminal/src/executable.rs"}),e[3]||(e[3]=i(" — shortcut and trait wrapper.",-1))])]),e[6]||(e[6]=t("h2",{id:"references",tabindex:"-1"},[i("References "),t("a",{class:"header-anchor",href:"#references","aria-label":'Permalink to "References"'},"​")],-1)),t("ul",null,[t("li",null,[n(a,{repo:"applications",path:"executables/terminal"})]),e[4]||(e[4]=t("li",null,[t("a",{href:"/explanation/architecture/executables/command_line_shell.html"},"Command line shell")],-1))])])}const v=o(d,[["render",u]]);export{x as __pageData,v as default};
